using System;using System.Data.Common;using System.Data.SQLite;using System.Globalization;using System.Text;using System.Text.Json;using OpenSim.Data;
class TestMigration:Migration{public TestMigration(DbConnection c,Resources a,string sub,string type):base(c,a,sub,type){}public int Find(string type)=>FindVersion(_conn,type);public void Execute(string[] batches)=>ExecuteScript(_conn,batches);}
class MigrationEngineReference{
 static void Exec(SQLiteConnection db,string sql){using var command=db.CreateCommand();command.CommandText=sql;command.ExecuteNonQuery();}
 static string Scalar(SQLiteConnection db,string sql){try{using var c=db.CreateCommand();c.CommandText=sql;return Convert.ToString(c.ExecuteScalar(),CultureInfo.InvariantCulture);}catch{return "X";}}
 static string Snapshot(SQLiteConnection db)=>Host.Hex(Scalar(db,"SELECT coalesce(group_concat(coalesce(name,'<null>')||':'||quote(version),'|'),'') FROM (SELECT name,version FROM migrations ORDER BY name,version)"))+":"+Host.Hex(Scalar(db,"SELECT coalesce(group_concat(name||':'||type,'|'),'') FROM (SELECT name,type FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' ORDER BY name,type)"))+":"+Host.Hex(Scalar(db,"SELECT coalesce(group_concat(quote(value),'|'),'') FROM (SELECT value FROM payload ORDER BY rowid)"));
 static void Main(){CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;string line;while((line=Console.ReadLine())!=null){Host.Input=JsonDocument.Parse(Encoding.UTF8.GetString(Convert.FromHexString(line))).RootElement;Host.Trace="";var input=Host.Input;using var db=new SQLiteConnection("Data Source=:memory:;Pooling=False");db.Open();if(input.GetProperty("setup").GetString() is string setup&&!string.IsNullOrEmpty(setup)){try{Exec(db,setup);}catch{Console.WriteLine("FIXTURE_EX");continue;}}var resources=new Resources();DbConnection connection=input.GetProperty("no_db").GetBoolean()?null:db;TestMigration migration=null;try{migration=new TestMigration(connection,resources,input.GetProperty("sub").GetString(),input.GetProperty("type").GetString());}catch{}string output="";
 foreach(var op in input.GetProperty("ops").EnumerateArray()){string result="-";try{if(migration==null)throw new Exception("constructor");switch(op.GetProperty("op").GetString()){case "update":migration.Update();break;case "table":migration.InitMigrationsTable();break;case "version":result=migration.Version.ToString();break;case "set":migration.Version=op.GetProperty("value").GetInt32();break;case "find":result=migration.Find(op.GetProperty("type").GetString()).ToString();break;case "execute":var values=op.GetProperty("batches");var batches=new string[values.GetArrayLength()];for(int i=0;i<batches.Length;++i)batches[i]=values[i].GetString();migration.Execute(batches);break;case "raw":Exec(db,op.GetProperty("sql").GetString());break;case "initialize":migration.Initialize(connection,resources,op.GetProperty("type").GetString(),op.GetProperty("sub").GetString());break;}}catch{result="EX";}output+=Host.Hex(result)+":"+Snapshot(db)+";";}
 Console.WriteLine(output+"|"+Host.Hex(Host.Trace));}}
}
